document.addEventListener("DOMContentLoaded",()=>{const s=document.querySelectorAll(".card-carousel-container");s.length&&s.forEach(r=>{const e=r.querySelector(".card-carousel-track"),i=Array.from(e.children),o=r.querySelector(".card-carousel-button.next"),n=r.querySelector(".card-carousel-button.prev");if(!e||!o||!n)return;const a=()=>{const l=e.querySelector(".carousel-item");return l?l.offsetWidth+20:300},c=()=>{n.disabled=e.scrollLeft<=5,o.disabled=e.scrollLeft+e.clientWidth>=e.scrollWidth-5};o.addEventListener("click",()=>{e.scrollBy({left:a(),behavior:"smooth"})}),n.addEventListener("click",()=>{e.scrollBy({left:-a(),behavior:"smooth"})});let t=!1;e.addEventListener("scroll",()=>{t||(window.requestAnimationFrame(()=>{c(),t=!1}),t=!0)},{passive:!0}),window.addEventListener("resize",()=>{t||(window.requestAnimationFrame(()=>{c(),t=!1}),t=!0)}),c()})});
